-- Adds Hustle & Muscle to a Studio that was already seeded. Safe to run twice.
begin;
update public.studio_projects set position = position + 1
  where not exists (select 1 from public.studio_projects where slug = 'hustle-and-muscle');
insert into public.studio_projects
  (slug, position, published, name, kind, category, tags, stamps, year, years, role_short, role, platform, status,
   live_url, docs_url, design_system_url, screenshots, facts, stats, entries)
values ($t$hustle-and-muscle$t$, 0, true, $t$Hustle & Muscle$t$, $t$Gym website$t$, $t$Fitness · Web design & build$t$, array[$t$web$t$, $t$brand$t$]::text[], array[$t$fitness$t$]::text[], 2026, $t$May–Nov 2026$t$, $t$Designer & builder · passion project$t$, $t$Designer and developer, passion project, building with Claude as an AI pair programmer$t$, $t$Web$t$, $t$live$t$, $t$https://hustle-and-muscle.vercel.app/$t$, $t$https://claude.ai/artifact/E8uSJ4pSD4oieDSy91Dntj$t$, $t$/docs/hustle-and-muscle-design-system.pdf$t$, $j$[{"label":"Homepage","src":"/projects/hustle-and-muscle/home.webp"},{"label":"Class cards","src":"/projects/hustle-and-muscle/classes.webp"},{"label":"Coach J.R. chat","src":"/projects/hustle-and-muscle/coach-jr.webp"}]$j$::jsonb, $j$[{"label":"Designed in May, built in November","value":"Hi-fi Figma designs first, then the build, in ten commits over two days."},{"label":"3 designs, 29 pages","value":"The shop, cart, classes and coach profiles were built from the design system alone."},{"label":"Coach J.R.","value":"A guided chat bot in English and Filipino, with a witty Bisaya voice."}]$j$::jsonb, $j$[{"value":"29","label":"pages from 3 Figma designs"},{"value":"2 days","label":"from Figma to a deployed site"},{"value":"2","label":"languages Coach J.R. speaks"}]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, May 2026","body":"A good friend turned out to own a gym, so I designed Hustle & Muscle a website in hi-fi Figma: the homepage, contact and coaches pages. Black ground, huge type, one hot orange and cut corners."},{"stage":"challenge","label":"Context & challenge","date":"November 2026","body":"Six months later I wanted those designs to be a real site. Three designed pages had to become every page a member would reach for (plans, classes, coaches, a shop, policies) without a backend and without the look falling apart."},{"stage":"approach","label":"Approach","date":"Along the way","body":"Tokens first: every color, size and corner from Figma became a named Tailwind token, so the 26 undesigned pages could match the three designed ones. Then one cart for everything, forms that open with the topic filled in, and Coach J.R., a guided bot instead of an AI one, because a gym bot should never make up a price."},{"stage":"outcome","label":"Outcome","date":"November 2026","body":"It's deployed on Vercel. Kirsten Corpuz, the gym's co-founder, has seen it, called it great, and plans to take it live after the third branch opens."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"Building with Claude turned six-month-old Figma frames into a working site in two days. The design calls stayed mine. Deciding what not to build (no AI, no backend, no payments yet) kept it honest."}]$j$::jsonb)
on conflict (slug) do nothing;
commit;
